import gurobipy as gp
from gurobipy import GRB
capacity_records = [r for r in LEGACY_RECORDS if r['source'].endswith('capacity.csv')]
product_records = [r for r in LEGACY_RECORDS if r['source'].endswith('products.csv')]
sections = []
capacities = {}
for rec in capacity_records:
    sid = str(rec['values']['SectionID'])
    cap = int(rec['values']['Capacity'])
    sections.append(sid)
    capacities[sid] = cap
products = []
values = {}
weights = {}
for rec in product_records:
    pname = str(rec['values']['ProductName'])
    val = int(rec['values']['Value'])
    wt = int(rec['values']['Weight'])
    products.append(pname)
    values[pname] = val
    weights[pname] = wt
if len(sections) == 0 or len(products) == 0:
    raise ValueError('Missing section or product data.')
for sid in sections:
    if sid not in capacities:
        raise ValueError(f'Missing capacity for section {sid}.')
for pname in products:
    if pname not in values or pname not in weights:
        raise ValueError(f'Missing value or weight for product {pname}.')
m = gp.Model('Supermarket_Section_Allocation')
x_vars = m.addVars(sections, products, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((values[p] * x_vars[s, p] for s in sections for p in products)), GRB.MAXIMIZE)
m.addConstrs((gp.quicksum((weights[p] * x_vars[s, p] for p in products)) <= capacities[s] for s in sections), name='')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')
